<template><section v-if="capture" aria-label="完整获授权研究原始记录"><p>项目声明目的：</p><pre>{{ capture.scope_original.payload.purpose }}</pre><p>原项目完整患者集合：{{ capture.scope_original.payload.patient_ids.join('、') }}；记录窗口 {{ capture.scope_original.payload.record_window.date_from }} 至 {{ capture.scope_original.payload.record_window.date_to }}。</p><p>授权登记依据：</p><pre>{{ capture.scope_original.payload.authorization_basis }}</pre><p>外部模型处理依据：</p><pre>{{ capture.scope_original.payload.external_model_use_basis }}</pre><article v-for="record in capture.records" :key="record.family+':'+record.record_id"><p>{{ families[record.family] }}；患者 {{ record.patient_id }}；记录 {{ record.record_id }}；{{ record.window_status==='unknown_clock'?'原日期未知':'原日历日期在声明范围' }}；父关联 {{ parents[record.parent_binding.status] }}。</p><dl><template v-for="(value,field) in record.original" :key="field"><dt>{{ fields[field]||field }}</dt><dd><pre>{{ value===null?'未记录（null）':String(value) }}</pre></dd></template></dl></article><p v-if="capture.records.length===0">所声明范围没有原记录；不会视作条件满足或疾病不存在。</p></section></template>
<script setup>
defineProps({capture:{type:Object,default:null}});
const families={patient_demographics:'有限人口学字段',registrations:'挂号记录',admissions:'住院记录',medical_records:'门诊病历',structured_medical_records:'结构化病历'},parents={patient_bound:'患者绑定一致',unknown_parent:'未知',missing_parent:'原父件缺失',patient_mismatch:'患者不一致'},fields={patient_id:'患者ID',sex:'原性别编码',birthday:'出生日期',symptom:'症状原文',result:'诊断结果原文',status:'原状态编码',time:'原时间',doctor_id:'医生ID',medical_record_id:'病历ID',registration_uuid:'挂号ID',sign_time:'签署时间',consultation_time:'就诊时间'};
</script>
